class Insan:
    def __init__(self, ad, soyad, eposta):
        self.ad = ad
        self.soyad = soyad
        self.eposta = eposta

    def kimlik_bilgisi(self):
        print(f'Kişi: {self.ad} {self.soyad} | E-posta: {self.eposta}')

class Ogrenci(Insan):  # Insan sınıfından miras alıyoruz
    def __init__(self, ad, soyad, eposta, ogrenci_no):
        super().__init__(ad, soyad, eposta)  # Ana sınıfın yapıcısını çağırır!
        self.ogrenci_no = ogrenci_no

    def ders_calis(self):
        print(f'{self.ad} ({self.ogrenci_no}) ders çalışıyor 📚')

class OgretimGorevlisi(Insan):
    def __init__(self, ad, soyad, eposta, unvan, bolum):
        super().__init__(ad, soyad, eposta)
        self.unvan = unvan
        self.bolum = bolum

    def ders_anlat(self):
        print(f'{self.unvan} {self.ad} {self.bolum} dersi anlatıyor 👨‍🏫')

class Memur(Insan):
    def __init__(self, ad, soyad, eposta, birim):
        super().__init__(ad, soyad, eposta)
        self.birim = birim

    def evrak_isle(self, evrak_adi):
        print(f'{self.ad} memuru {evrak_adi} evrakını onayladı.')

Alt sınıf, ana sınıftaki bir metodu aynı isimle yeniden yazarak davranışını değiştirebilir:

class Ogrenci(Insan):
    # ...
    def kimlik_bilgisi(self):  # Ezme (Override)
        print(f'🎓 Öğrenci: {self.ad} {self.soyad} | No: {self.ogrenci_no}')

Bu durum Çok Biçimliliğin (Polymorphism) temelini oluşturur.

class OgretimGorevlisi(Insan):
    # ...
    def kimlik_bilgisi(self):
        super().kimlik_bilgisi()  # Önce ana sınıfın çıktısını verir
        print(f'Ünvan: {self.unvan} | Bölüm: {self.bolum}')  # Ekstra bilgi basar

class Urun:
    def __init__(self, baslik, fiyat):
        self.baslik = baslik
        self.fiyat = fiyat

class Telefon(Urun):
    def __init__(self, baslik, fiyat, dahili_hafiza):
        super().__init__(baslik, fiyat)
        self.dahili_hafiza = dahili_hafiza

tel = Telefon('Galaxy S24', 45000, 256)
print(f'{tel.baslik} ({tel.dahili_hafiza} GB) -> {tel.fiyat} TL')

class Laptop(Urun):
    def __init__(self, baslik, fiyat, ram_gb):
        super().__init__(baslik, fiyat)
        self.ram_gb = ram_gb

    def ozellikler(self):
        print(f'💻 {self.baslik} - {self.ram_gb} GB RAM - {self.fiyat} TL')

lap = Laptop('ThinkPad', 35000, 32)
lap.ozellikler()

class Urun:
    # ...
    def indirim_uygula(self, yuzde):
        self.fiyat = self.fiyat * (1 - yuzde/100)
        print(f'{self.baslik} yeni fiyat: {self.fiyat:.2f} TL')

tel.indirim_uygula(10)  # Hem telefon hem laptop bu metodu kullanabilir!

class Hesap:
    def __init__(self, iban, bakiye):
        self.iban = iban
        self.bakiye = bakiye

class VadeliHesap(Hesap):
    def __init__(self, iban, bakiye, faiz_orani):
        super().__init__(iban, bakiye)
        self.faiz_orani = faiz_orani

    def faiz_getirisi(self):
        return self.bakiye * (self.faiz_orani / 100)

class Arac:
    def __init__(self, plaka, gunluk_ucret):
        self.plaka = plaka
        self.gunluk_ucret = gunluk_ucret

    def kira_hesapla(self, gun):
        return self.gunluk_ucret * gun

a1 = Arac('28 AB 123', 800)
print('3 Günlük Kira:', a1.kira_hesapla(3), 'TL')

